import numpy as np
import pandas as pd
from datetime import datetime, date, timedelta
import calendar

def r_time_update(time, updates=None, year=None, month=None, yday=None, 
                  mday=None, wday=None, hour=None, minute=None, second=None, 
                  tz=None, roll_month="preday", roll_dst=("boundary", "post"), 
                  week_start=1, exact=False):

    if time is None:
        return time

    # Handle array-like check
    if isinstance(time, (np.ndarray, pd.Series, list)) and len(time) == 0:
        return time

    # Handle scalar input conversion
    is_scalar = not isinstance(time, (np.ndarray, pd.Series, list))
    time_arr = np.atleast_1d(time)

    # 1. Resolve updates mapping (R's logic: updates_list + updts_params)
    updts_params = {
        'year': year, 'month': month, 'yday': yday, 'mday': mday, 
        'wday': wday, 'hour': hour, 'minute': minute, 'second': second
    }

    final_updates = {}
    if updates is not None:
        if isinstance(updates, dict):
            final_updates = updates.copy()
        else:
            final_updates = {}

    for nm, val in updts_params.items():
        if val is not None:
            if nm not in final_updates or final_updates[nm] is None:
                final_updates[nm] = val
            else:
                final_updates[nm] = np.array(final_updates[nm]) + np.array(val)

    final_updates = {k: v for k, v in final_updates.items() if v is not None}

    # Detect input type for return type logic
    is_date_input = False
    if len(time_arr) > 0:
        first_el = time_arr[0]
        if isinstance(first_el, (date, np.datetime64)) and not isinstance(first_el, datetime):
            is_date_input = True
        elif isinstance(first_el, str) and len(first_el) <= 10 and ' ' not in first_el:
            is_date_input = True
        elif pd.api.types.is_datetime64_any_dtype(time_arr) and not pd.api.types.is_datetime64_ns_dtype(time_arr):
            is_date_input = True

    # Convert to pandas DatetimeIndex for consistent access
    ts_index = pd.to_datetime(time_arr, errors='coerce')
    target_tz = tz if tz else 'UTC'

    def update_single(t, upd_row):
        if pd.isna(t):
            return pd.NaT

        # Base values
        y, m, d = t.year, t.month, t.day
        h, mi, s = t.hour, t.minute, t.second

        # Update logic matching C_time_update behavior
        if 'year' in upd_row:
            y = int(upd_row['year'])

        if 'month' in upd_row:
            m_val = int(upd_row['month'])
            # R month rollover: 13 becomes next year, month 1
            y += (m_val - 1) // 12
            m = (m_val - 1) % 12 + 1

        if 'yday' in upd_row:
            yday_val = int(upd_row['yday'])
            # yday is 1-indexed from Jan 1st
            dt_yday = datetime(y, 1, 1) + timedelta(days=yday_val - 1)
            y, m, d = dt_yday.year, dt_yday.month, dt_yday.day
        elif 'mday' in upd_row:
            mday_val = int(upd_row['mday'])
            last_day = calendar.monthrange(y, m)[1]
            if mday_val > last_day:
                if roll_month == "preday":
                    d = last_day
                else: # postday etc
                    dt_rolled = datetime(y, m, 1) + timedelta(days=mday_val - 1)
                    y, m, d = dt_rolled.year, dt_rolled.month, dt_rolled.day
            else:
                d = mday_val

        if 'hour' in upd_row: h = int(upd_row['hour'])
        if 'minute' in upd_row: mi = int(upd_row['minute'])
        if 'second' in upd_row: s = int(upd_row['second'])

        try:
            res = pd.Timestamp(year=y, month=m, day=d, hour=h, minute=mi, second=s)
        except ValueError:
            res = pd.Timestamp(year=y, month=m, day=1, hour=h, minute=mi, second=s)
            res += timedelta(days=d-1)

        if res.tzinfo is None:
            res = res.tz_localize(target_tz)
        else:
            res = res.tz_convert(target_tz)

        return res

    n = len(time_arr)
    results = []
    for i in range(n):
        row = {}
        for k, v in final_updates.items():
            if isinstance(v, np.ndarray):
                row[k] = v[i] if v.size == n else v[0]
            else:
                row[k] = v
        results.append(update_single(ts_index[i], row))

    # R Return Type logic
    no_time_updates = not any(k in final_updates for k in ['hour', 'minute', 'second', 'tz'])

    if is_date_input and no_time_updates:
        # Return as Date (numpy datetime64[D] or list of date)
        final_res = np.array([t.date() if pd.notnull(t) else np.nan for t in results])
    else:
        # Return as POSIXct (numpy array of datetimes)
        final_res = np.array(results)

    if is_scalar:
        return final_res[0]
    return final_res
